package order

type Order struct {            // unexported fields: package-level encapsulation
    customer CustomerID
    lines    []Line
}

func NewOrder(c CustomerID) *Order { return &Order{customer: c} }

func (o *Order) AddLine(l Line) error {
    if o.total().Add(l.Price()).Cents() > MaxTotalCents {
        return ErrOrderLimitExceeded
    }
    o.lines = append(o.lines, l)
    return nil
}

func (o *Order) Lines() []Line { return slices.Clone(o.lines) }  // no aliasing
